-- TECNO Sales Academy: private employee training. Run in trusted Supabase SQL editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',role text not null default 'learner' check(role in ('learner','trainer','admin')),is_employee boolean not null default false,is_active boolean not null default false,region text,created_at timestamptz not null default now());
alter table public.profiles alter column is_active set default false;
create or replace function public.handle_new_academy_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new;end;$$;
drop trigger if exists academy_user_created on auth.users;
create trigger academy_user_created after insert on auth.users for each row execute function public.handle_new_academy_user();
create or replace function public.academy_is_employee() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and is_employee=true and is_active=true);$$;
create or replace function public.academy_is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and is_employee=true and is_active=true and role='admin');$$;
create table if not exists public.catalog_products (id uuid primary key default gen_random_uuid(),slug text not null unique,series text not null default '',model text not null default '',name_ar text not null,name_en text not null,description_ar text not null default '',description_en text not null default '',specs jsonb not null default '{}'::jsonb check(jsonb_typeof(specs)='object'),fabe jsonb not null default '{}'::jsonb check(jsonb_typeof(fabe)='object'),image_path text not null default '',is_published boolean not null default false,updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id));
create table if not exists public.academy_courses (id uuid primary key default gen_random_uuid(),slug text not null unique,title_ar text not null,title_en text not null,description_ar text not null default '',description_en text not null default '',sort_order integer not null default 0,is_published boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.academy_lessons (id uuid primary key default gen_random_uuid(),course_id uuid not null references public.academy_courses(id) on delete cascade,title_ar text not null,title_en text not null,body_ar text not null default '',body_en text not null default '',sort_order integer not null default 0,is_published boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.sales_scenarios (id uuid primary key default gen_random_uuid(),slug text not null unique,title_ar text not null,title_en text not null,description_ar text not null default '',description_en text not null default '',graph jsonb not null check(jsonb_typeof(graph)='object'),is_published boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.simulation_attempts (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade default auth.uid(),scenario_id uuid not null references public.sales_scenarios(id) on delete cascade,score integer not null check(score between 0 and 100),answers jsonb not null default '[]'::jsonb check(jsonb_typeof(answers)='array'),created_at timestamptz not null default now());
create table if not exists public.lesson_completions (user_id uuid not null references public.profiles(id) on delete cascade default auth.uid(),lesson_id uuid not null references public.academy_lessons(id) on delete cascade,completed_at timestamptz not null default now(),primary key(user_id,lesson_id));
create or replace function public.academy_touch_product() returns trigger language plpgsql security definer set search_path='' as $$begin new.updated_at=now();new.updated_by=auth.uid();return new;end;$$;
drop trigger if exists academy_product_touch on public.catalog_products;
create trigger academy_product_touch before insert or update on public.catalog_products for each row execute function public.academy_touch_product();
alter table public.profiles enable row level security;
drop policy if exists academy_profiles_read on public.profiles;
create policy academy_profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.academy_is_admin());
drop policy if exists academy_profiles_admin_update on public.profiles;
create policy academy_profiles_admin_update on public.profiles for update to authenticated using(public.academy_is_admin()) with check(public.academy_is_admin());
alter table public.catalog_products enable row level security;
drop policy if exists catalog_products_read on public.catalog_products;
create policy catalog_products_read on public.catalog_products for select to authenticated using(public.academy_is_employee());
drop policy if exists catalog_products_admin on public.catalog_products;
create policy catalog_products_admin on public.catalog_products for all to authenticated using(public.academy_is_admin()) with check(public.academy_is_admin());
alter table public.academy_courses enable row level security;
drop policy if exists academy_courses_read on public.academy_courses;
create policy academy_courses_read on public.academy_courses for select to authenticated using(public.academy_is_employee());
drop policy if exists academy_courses_admin on public.academy_courses;
create policy academy_courses_admin on public.academy_courses for all to authenticated using(public.academy_is_admin()) with check(public.academy_is_admin());
alter table public.academy_lessons enable row level security;
drop policy if exists academy_lessons_read on public.academy_lessons;
create policy academy_lessons_read on public.academy_lessons for select to authenticated using(public.academy_is_employee());
drop policy if exists academy_lessons_admin on public.academy_lessons;
create policy academy_lessons_admin on public.academy_lessons for all to authenticated using(public.academy_is_admin()) with check(public.academy_is_admin());
alter table public.sales_scenarios enable row level security;
drop policy if exists sales_scenarios_read on public.sales_scenarios;
create policy sales_scenarios_read on public.sales_scenarios for select to authenticated using(public.academy_is_employee());
drop policy if exists sales_scenarios_admin on public.sales_scenarios;
create policy sales_scenarios_admin on public.sales_scenarios for all to authenticated using(public.academy_is_admin()) with check(public.academy_is_admin());
alter table public.simulation_attempts enable row level security;
alter table public.lesson_completions enable row level security;
drop policy if exists attempts_read on public.simulation_attempts;
create policy attempts_read on public.simulation_attempts for select to authenticated using((user_id=auth.uid() and public.academy_is_employee()) or public.academy_is_admin());
drop policy if exists attempts_insert on public.simulation_attempts;
create policy attempts_insert on public.simulation_attempts for insert to authenticated with check(user_id=auth.uid() and public.academy_is_employee());
drop policy if exists completions_read on public.lesson_completions;
create policy completions_read on public.lesson_completions for select to authenticated using((user_id=auth.uid() and public.academy_is_employee()) or public.academy_is_admin());
drop policy if exists completions_insert on public.lesson_completions;
create policy completions_insert on public.lesson_completions for insert to authenticated with check(user_id=auth.uid() and public.academy_is_employee());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('staff-assets','staff-assets',false,10485760,array['image/webp','image/png','image/jpeg','image/svg+xml']) on conflict(id) do update set public=false;
drop policy if exists academy_storage_read on storage.objects;
create policy academy_storage_read on storage.objects for select to authenticated using(bucket_id='staff-assets' and public.academy_is_employee());
drop policy if exists academy_storage_admin_insert on storage.objects;
create policy academy_storage_admin_insert on storage.objects for insert to authenticated with check(bucket_id='staff-assets' and public.academy_is_admin());
drop policy if exists academy_storage_admin_update on storage.objects;
create policy academy_storage_admin_update on storage.objects for update to authenticated using(bucket_id='staff-assets' and public.academy_is_admin()) with check(bucket_id='staff-assets' and public.academy_is_admin());
drop policy if exists academy_storage_admin_delete on storage.objects;
create policy academy_storage_admin_delete on storage.objects for delete to authenticated using(bucket_id='staff-assets' and public.academy_is_admin());
-- First admin: update public.profiles set role='admin',is_employee=true,is_active=true where id='<verified uuid>';
-- Client-side simulation scores are formative, not secure HR measurements.
